#include <bits/stdc++.h>
using namespace std;
int main() {
    string s, p;
    cin >> s >> p;
    int m = p.size();
    vector<int> pi(m, 0);
    for (int i = 1; i < m; i++) {
        int k = pi[i - 1];
        while (k > 0 && p[i] != p[k]) k = pi[k - 1];
        if (p[i] == p[k]) k++;
        pi[i] = k;
    }
    int count = 0, first = -1, k = 0;
    for (int i = 0; i < (int)s.size(); i++) {
        while (k > 0 && (k == m || s[i] != p[k])) k = pi[k - 1];
        if (s[i] == p[k]) k++;
        if (k == m) {
            count++;
            if (first == -1) first = i - m + 1;
        }
    }
    printf("%d\n%d\n", count, first);
    return 0;
}
